input.command:
S=/tmp/claude-1000/-home-sauyon-devel-dotfiles/455aad21-0d10-4f23-a977-51406866406f/scratchpad/wg; mkdir -p $S/pA $S/pB; cat > $S/t.html <<'EOF'
<html><body style="font:40px sans-serif"><div id=o>start</div><script>
const o=document.getElementById('o');
o.textContent='gpu='+(!!navigator.gpu)+' secure='+isSecureContext;
if(navigator.gpu) navigator.gpu.requestAdapter().then(a=>{o.textContent+=' adapter='+(a?(a.info&&a.info.vendor+'/'+a.info.architecture||'yes'):'null')}).catch(e=>{o.textContent+=' err='+e});
</script></body></html>
EOF
echo 'user_pref("dom.webgpu.enabled", true);' > $S/pB/user.js
for p in pA pB; do timeout 60 zen-beta --no-remote --profile $S/$p --headless --window-size 1400,300 --screenshot $S/$p.png file://$S/t.html >/dev/null 2>&1; echo "$p exit=$?"; done; ls $S/*.png
